// Vite copies every imported original image into dist/_assets even when the
// page only references the resized renditions generated by astro:assets.
// Delete generated image files in dist/_assets that no built HTML/CSS/JS
// mentions. Runs from the postbuild hook, after terser.
import { readdirSync, readFileSync, statSync, unlinkSync } from 'node:fs';
import { join, extname } from 'node:path';
import { fileURLToPath } from 'node:url';

// Default target is dist/; an explicit path lets the same script be verified
// against a throwaway build without touching dist/.
//
// fileURLToPath, not URL.pathname: pathname on a file: URL is percent-encoded
// and keeps the leading slash before the drive letter on Windows, so
// file:///C:/repos/... became "/C:/repos/...", path.join prepended the drive
// again, and every Windows build died in postbuild with
// ENOENT scandir 'C:\C:\repos\...\dist\'.
const DIST = process.argv[2] ?? fileURLToPath(new URL('../dist/', import.meta.url));
const ASSETS = join(DIST, '_assets');

// This script DELETES build output, so the reference scan must be
// fail-safe: a file it forgets to read is a reference it cannot see, and an
// unseen reference means a still-used image is silently removed. An
// allow-list of extensions to scan gets that backwards — it goes stale the
// moment the build emits a format nobody listed (an .svg sprite with an
// <image href>, a .map, a .txt), and the failure is invisible until a live
// page 404s. So: scan EVERYTHING except the payload formats that cannot
// contain a URL reference to another asset. Adding an entry below is a
// deliberate act; forgetting one only costs a few milliseconds of scanning.
const OPAQUE_EXTENSIONS = new Set([
  // raster / video payloads
  '.webp', '.avif', '.png', '.jpg', '.jpeg', '.gif', '.ico', '.bmp', '.tiff',
  '.mp4', '.webm', '.ogv', '.mp3', '.ogg', '.wav',
  // fonts
  '.woff', '.woff2', '.ttf', '.otf', '.eot',
  // archives / binaries
  '.zip', '.gz', '.br', '.pdf', '.wasm',
]);

const walk = (dir) =>
  readdirSync(dir).flatMap((name) => {
    const p = join(dir, name);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });

// No try/catch on the read: if a file cannot be scanned, the script must fail
// loudly and prune nothing rather than proceed with an incomplete picture.
const referenced = walk(DIST)
  .filter((p) => !OPAQUE_EXTENSIONS.has(extname(p).toLowerCase()))
  .map((p) => readFileSync(p, 'utf8'))
  .join('\n');

// Which files are ELIGIBLE for deletion. This deliberately mirrors the raster
// formats astro:assets can emit rather than hard-coding one of them: the site
// now ships AVIF alongside WebP (<Picture format={['avif','webp']}>), and an
// eligibility list that still said `.webp` would leave every orphaned AVIF
// original behind — silently undoing the prune for half the corpus.
//
// Note the asymmetry with OPAQUE_EXTENSIONS above, which is a SCAN list: that
// one must be as SMALL as possible (anything not on it gets read for
// references), this one as SMALL as possible too (anything not on it is never
// deleted). Both err towards keeping files.
const PRUNABLE_EXTENSIONS = new Set(['.webp', '.avif', '.png', '.jpg', '.jpeg', '.gif']);

let removed = 0;
let bytes = 0;
for (const file of walk(ASSETS).filter((p) => PRUNABLE_EXTENSIONS.has(extname(p).toLowerCase()))) {
  const basename = file.slice(file.lastIndexOf('/') + 1);
  if (!referenced.includes(basename)) {
    bytes += statSync(file).size;
    unlinkSync(file);
    removed++;
  }
}
console.log(`prune-unused-images: removed ${removed} unreferenced image(s), ${(bytes / 1024).toFixed(0)} kB`);
